// Command unicodegen writes the Unicode tables of pbs-gocompat from the Go unicode package, plus
// a checksum over every rune that the Rust tests recompute from those tables.
//
// Run from the repository root (then format the output with the pinned rustfmt):
//
//	go run ./rust/crates/gocompat/testdata/go/unicodegen rust/crates/gocompat
//	rustfmt +nightly-2026-11-13 --edition 2024 rust/crates/gocompat/src/unicode/tables.rs
package main

import (
	"fmt"
	"hash/fnv"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"unicode"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: unicodegen <crate dir>")
		os.Exit(2)
	}
	crate := os.Args[1]
	write(filepath.Join(crate, "src", "unicode", "tables.rs"), tables())
	write(filepath.Join(crate, "testdata", "go", "unicodegen", "checksum.txt"), checksum())
}

func write(path, content string) {
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// num prints n in decimal with "_" every three digits once it has five or more digits, the
// form clippy's unreadable_literal accepts.
func num(n int64) string {
	neg := n < 0
	if neg {
		n = -n
	}
	s := fmt.Sprint(n)
	if len(s) >= 5 {
		var b strings.Builder
		pre := len(s) % 3
		if pre > 0 {
			b.WriteString(s[:pre])
		}
		for i := pre; i < len(s); i += 3 {
			if b.Len() > 0 {
				b.WriteByte('_')
			}
			b.WriteString(s[i : i+3])
		}
		s = b.String()
	}
	if neg {
		return "-" + s
	}
	return s
}

func isSurrogate(r rune) bool { return r >= 0xD800 && r <= 0xDFFF }

// ranges collects maximal [lo, hi] runs of runes for which pred holds.
func ranges(pred func(rune) bool) [][2]rune {
	var out [][2]rune
	start := rune(-1)
	for r := rune(0); r <= unicode.MaxRune+1; r++ {
		in := r <= unicode.MaxRune && pred(r)
		switch {
		case in && start < 0:
			start = r
		case !in && start >= 0:
			out = append(out, [2]rune{start, r - 1})
			start = -1
		}
	}
	return out
}

func rangeTable(b *strings.Builder, name, doc string, pred func(rune) bool) {
	fmt.Fprintf(b, "/// %s\n", doc)
	fmt.Fprintf(b, "pub(super) static %s: &[(u32, u32)] = &[\n", name)
	for _, r := range ranges(pred) {
		fmt.Fprintf(b, "    (%s, %s),\n", num(int64(r[0])), num(int64(r[1])))
	}
	b.WriteString("];\n\n")
}

func tables() string {
	var b strings.Builder
	fmt.Fprintf(&b, "//! Unicode tables generated by `testdata/go/unicodegen` from %s (Unicode %s).\n",
		runtime.Version(), unicode.Version)
	b.WriteString("//! Do not edit; regenerate instead.\n\n")
	rangeTable(&b, "LETTER", "Go: `unicode.IsLetter` (categories Lu, Ll, Lt, Lm, Lo).", unicode.IsLetter)
	rangeTable(&b, "DIGIT", "Go: `unicode.IsDigit` (category Nd).", unicode.IsDigit)
	rangeTable(&b, "PRINT", "Go: `unicode.IsPrint` (L, M, N, P, S and the ASCII space).", unicode.IsPrint)
	rangeTable(&b, "GRAPHIC", "Go: `unicode.IsGraphic` (L, M, N, P, S, Zs).", unicode.IsGraphic)
	rangeTable(&b, "SPACE", "Go: `unicode.IsSpace`.", unicode.IsSpace)

	b.WriteString("/// Go: `unicode.CaseRanges` as (lo, hi, upper delta, lower delta, title delta);\n")
	b.WriteString("/// a delta of `UPPER_LOWER` marks an alternating upper/lower sequence.\n")
	b.WriteString("pub(super) static CASE_RANGES: &[(u32, u32, i32, i32, i32)] = &[\n")
	for _, cr := range unicode.CaseRanges {
		fmt.Fprintf(&b, "    (%s, %s, %s, %s, %s),\n", num(int64(cr.Lo)), num(int64(cr.Hi)),
			num(int64(cr.Delta[0])), num(int64(cr.Delta[1])), num(int64(cr.Delta[2])))
	}
	b.WriteString("];\n\n")

	// Runes whose SimpleFold differs from the CaseRanges fallback (Go's asciiFold and caseOrbit).
	type pair struct{ from, to rune }
	var orbit []pair
	for r := rune(0); r <= unicode.MaxRune; r++ {
		fallback := r
		if l := unicode.ToLower(r); l != r {
			fallback = l
		} else {
			fallback = unicode.ToUpper(r)
		}
		if f := unicode.SimpleFold(r); f != fallback {
			orbit = append(orbit, pair{r, f})
		}
	}
	sort.Slice(orbit, func(i, j int) bool { return orbit[i].from < orbit[j].from })
	b.WriteString("/// Runes whose `unicode.SimpleFold` is not the `CaseRanges` fallback (Go's `asciiFold`\n")
	b.WriteString("/// and `caseOrbit` tables), as (from, to).\n")
	b.WriteString("pub(super) static FOLD_ORBIT: &[(u32, u32)] = &[\n")
	for _, p := range orbit {
		fmt.Fprintf(&b, "    (%s, %s),\n", num(int64(p.from)), num(int64(p.to)))
	}
	b.WriteString("];\n")
	return b.String()
}

// checksum hashes, for every non-surrogate rune, the property flags and case mappings.
func checksum() string {
	h := fnv.New64a()
	buf := make([]byte, 4)
	put := func(v uint32) {
		buf[0], buf[1], buf[2], buf[3] = byte(v), byte(v>>8), byte(v>>16), byte(v>>24)
		h.Write(buf)
	}
	for r := rune(0); r <= unicode.MaxRune; r++ {
		if isSurrogate(r) {
			continue
		}
		var flags uint32
		for i, f := range []func(rune) bool{unicode.IsLetter, unicode.IsDigit, unicode.IsPrint, unicode.IsGraphic, unicode.IsSpace} {
			if f(r) {
				flags |= 1 << i
			}
		}
		put(uint32(r))
		put(flags)
		put(uint32(unicode.ToLower(r)))
		put(uint32(unicode.ToUpper(r)))
		put(uint32(unicode.ToTitle(r)))
		put(uint32(unicode.SimpleFold(r)))
	}
	return fmt.Sprintf("%016x\n", h.Sum64())
}
